  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04", "C32", "C47"],
      "claim": "Direct absolute oral bioavailability measurements in healthy subjects consistently exceed 20%, including encainide 32±7%, daridorexant 62%, and brexpiprazole 95%."
    },
    {
      "card_ids": ["C25", "C38", "C17"],
      "claim": "Population pharmacokinetic model estimates also exceed 20%, including letermovir 93.8%, daridorexant F=0.41, and piperaquine F=0.77."
    },
    {
      "card_ids": ["C31", "C06", "C27"],
      "claim": "Even the lowest reported numeric bioavailability values remain at or above the 20% threshold, such as encainide 20-30%, letermovir ~35% in HCT patients, and nabumetone active metabolite 38%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All transferred evidence molecules have numeric oral bioavailability estimates at or above 20%, with multiple direct absolute measurements in healthy subjects; therefore high oral bioavailability is supported.",
  "evidence_gaps": [
    "One qualitative low-bioavailability record (C08) conflicts with numeric values for the same molecule, but direct numeric absolute measurements dominate.",
    "Some records come from disease populations or model-based estimates, but they remain consistent with the high-bioavailability direction."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C04", "C32", "C47", "C25", "C38", "C17", "C31", "C06", "C27"],
